21	import net.officefloor.hq.app.settings.SettingsService;
22	import net.officefloor.hq.app.sheet.SheetService;
23	import org.springframework.stereotype.Service;
24	import org.springframework.transaction.annotation.Transactional;
25	
26	/** The claims people on each sheet make. A claim left without a date is dated the sheet's entry date,
27	 * or its today when that is off. A claim's
28	 * due-by is fixed when it is added, from the terms of its person's grade in force on its date. Only a
29	 * DRAFT claim can be edited. No claim dated inside a closed period (not only soft-closed) can be added,
30	 * edited or change status; one added inside a soft-closed period is a late entry, and none can be added or edited to a date after its person's retirement date. A claim with a
31	 * negative amount is a correction: it is refused unless it names, by number, a SETTLED claim of the same
32	 * person; a claim that is not a correction names none. */
33	@Service
34	public class ClaimService {
35	
36	    private final ClaimRepository claims;
37	    private final ClaimLogRepository logs;
38	    private final PersonRepository people;
39	    private final RollupService rollup;
40	    private final SheetService sheets;
41	    private final PeriodRepository periods;
42	    private final SettingsService settings;
43	    private final PersonWatchRepository watches;
44	    private final Audit audit;
45	
46	    public ClaimService(ClaimRepository claims, ClaimLogRepository logs, PersonRepository people, RollupService rollup, SheetService sheets,
47	            PeriodRepository periods, SettingsService settings, PersonWatchRepository watches, Audit audit) {
48	        this.watches = watches;
49	        this.claims = claims;
50	        this.logs = logs;
51	        this.people = people;
52	        this.rollup = rollup;
53	        this.sheets = sheets;
54	        this.periods = periods;
55	        this.settings = settings;
56	        this.audit = audit;
57	    }
58	
59	    /** The sheet's claims, newest first. */
60	    @Transactional(readOnly = true)
61	    public List<Claim> list(String sheetId) {
62	        return claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
63	    }
64	
65	    /** The status logs of the claims, by claim id, each oldest first. */
66	    @Transactional(readOnly = true)
67	    public Map<Long, List<ClaimLog>> logsOf(List<Claim> of) {
68	        if (of.isEmpty()) return Map.of();
69	        return logs.findByClaimIdInOrderByIdAsc(of.stream().map(Claim::getId).toList()).stream()
70	                .collect(Collectors.groupingBy(ClaimLog::getClaimId));
71	    }
72	
73	    @Transactional
74	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
75	            String corrects) {
76	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
77	        RollupService.Snapshot before = rollup.snapshot(sheetId);
78	        LocalDate dated = date != null ? date : sheets.entryDate(sheetId);
79	        refuseClosed(sheetId, dated);
80	        person.requireClaimable(dated);
81	        refuseBadCorrection(sheetId, personId, amount, corrects);
82	        Claim claim = new Claim(sheetId, personId, amount, dated, noteOf(note), corrects);
83	        claim.setDueBy(dated.plusDays(termsOf(sheetId, person, dated)));
84	        claim.setListed(sheets.nextInSequence(sheetId, "listed"));
85	        claim.setLateEntry(periods.softClosedOn(sheetId, dated));
86	        claim = claims.saveAndFlush(claim);
87	        log(user, person, claim);
88	        record("CLAIM_ADDED", user, person, claim, claim.getNumber());
89	        if (claim.isLateEntry()) record("LATE_ENTRY", user, person, claim, claim.getNumber());
90	        rollup.recordSince(sheetId, user, before);
91	        return claim;
92	    }
93	
94	    @Transactional
95	    public Claim update(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
96	            String corrects) {
97	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
98	        if (claim.isLockedFor(user, sheets.today(sheetId))) throw new ClaimLockedException();
99	        LocalDate dated = date != null ? date : sheets.entryDate(sheetId);
100	        refuseClosed(sheetId, claim.getDate());
101	        refuseClosed(sheetId, dated);
102	        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimNotEditableException();
103	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
104	                .orElseThrow(PersonNotFoundException::new);
105	        person.requireClaimable(dated);
106	        refuseBadCorrection(sheetId, person.getId(), amount, corrects);
107	        RollupService.Snapshot before = rollup.snapshot(sheetId);
108	        claim.setAmount(amount);
109	        claim.setCorrects(corrects);
110	        claim.setDate(dated);
111	        claim.setNote(noteOf(note));
112	        claim.unlock();
113	        claims.flush();
114	        record("CLAIM_EDITED", user, person, claim, claim.getNumber());
115	        rollup.recordSince(sheetId, user, before);
116	        return claim;
117	    }
118	
119	    /** Open the claim's editor for {@code user}, locking the claim for everyone else until it is saved
120	     * (see {@link #update}) or cancelled (see {@link #unlock}), or the sheet's today changes. Refused,
121	     * taking no lock, when the claim cannot be edited (not a DRAFT, or dated in a closed period) or
122	     * another user holds its lock. */
123	    @Transactional
124	    public Claim lock(String sheetId, String user, long claimId) {
125	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
126	        LocalDate today = sheets.today(sheetId);
127	        refuseClosed(sheetId, claim.getDate());
128	        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimNotEditableException();
129	        if (claim.isLockedFor(user, today)) throw new ClaimLockedException();
130	        claim.lock(user, today);
131	        return claim;
132	    }
133	
134	    /** Close {@code user}'s editor of the claim without saving, releasing the lock it holds; a lock
135	     * another user holds is left alone. */
136	    @Transactional
137	    public Claim unlock(String sheetId, String user, long claimId) {
138	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
139	        if (user.equals(claim.getLockedBy())) claim.unlock();
140	        return claim;
141	    }
142	
143	    /** Move the claim to {@code next}; refused when the user's role may not open, settle or void it (see
144	     * {@link SettingsService#allowed}), and when its current status does not allow it (a PENDING
145	     * claim can only be voided here: it is approved or rejected instead). Settling it fixes what is due
146	     * on it then (the figure it is bound to, when a statement bound it, otherwise its person's rate then)
147	     * together with its late charge then (none on a correction); the user who opened it cannot settle it,
148	     * and a clerk's settle of it when that due is above the sheet's clerk limit (a due that is n/a is
149	     * within any limit) leaves it PENDING instead, fixing nothing, until a steward approves or rejects
150	     * it. A claim deferred on the sheet's today cannot be settled, nor one without proofs whose due is
151	     * above the proof threshold in force on its date (refused before the clerk limit is considered). A
152	     * SETTLED claim can only be voided by a steward, and only while the sheet's today is at most 7 days
153	     * after its settlement (its status log's SETTLED date); its frozen figure then leaves every total and
154	     * is recorded as reversed. A voided claim keeps its number, if it had one. */
155	    @Transactional
156	    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next) {
157	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
158	        Action action = switch (next) {
159	            case OPEN -> Action.OPEN;
160	            case SETTLED -> Action.SETTLE;
161	            case VOID -> Action.VOID;
162	            default -> null;
163	        };
164	        if (action != null && !settings.allowed(sheetId, user, action)) throw new ClaimNotStewardException();
165	        refuseClosed(sheetId, claim.getDate());
166	        if (!claim.getStatus().canBecome(next) || (claim.getStatus() == ClaimStatus.PENDING && next != ClaimStatus.VOID)) {
167	            throw new ClaimStatusChangeException();
168	        }
169	        boolean reversing = claim.getStatus() == ClaimStatus.SETTLED;
170	        if (reversing) refuseLateVoid(sheetId, user, claim);
171	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) throw new ClaimStatusChangeException();
172	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) throw new ClaimSelfSettleException();
173	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
174	                .orElseThrow(PersonNotFoundException::new);
175	        if (next == ClaimStatus.OPEN) refuseNoteless(claim, rollup.shownOf(claim, person));
176	        RollupService.Snapshot before = rollup.snapshot(sheetId);
177	        String number = claim.getNumber();
178	        if (next == ClaimStatus.OPEN) {
179	            number = nextNumber(sheetId, claim.getDate());
180	            claim.setOpenedBy(user);
181	        }
182	        if (next == ClaimStatus.SETTLED) {
183	            BigDecimal figure = claim.isStated() ? claim.getStatedDue() : rollup.dueOf(claim, person);
184	            BigDecimal due = rollup.liveDueOf(claim, figure);
185	            refuseUnproved(claim, due);
186	            if (overLimit(sheetId, user, due)) next = ClaimStatus.PENDING;
187	            else claim.setSettledDue(due);
188	        }
189	        claim.setStatus(next);
190	        claim.setNumber(number);
191	        claims.flush();
192	        log(user, person, claim);
193	        String event = switch (next) {
194	            case OPEN -> "CLAIM_OPENED";
195	            case PENDING -> "CLAIM_PENDING";
196	            case SETTLED -> "CLAIM_SETTLED";
197	            case VOID -> "CLAIM_VOIDED";
198	            case DRAFT -> throw new IllegalStateException();
199	        };
200	        if (next == ClaimStatus.SETTLED) {
201	            record(event, user, person, claim, number, "due=" + dueText(claim.getSettledDue()));
202	            notifyWatchers(user, person, claim);
203	        } else if (reversing) {
204	            record(event, user, person, claim, number, "reversed=" + dueText(claim.getSettledDue()));
205	        } else {
206	            record(event, user, person, claim, number);
207	        }
208	        rollup.recordSince(sheetId, user, before);
209	        return claim;
210	    }
211	
212	    /** Defer an OPEN claim until {@code until}, a date after the sheet's today: until the sheet's today
213	     * reaches it the claim counts in no total, is not overdue, cannot be settled and is left unbound by a
214	     * statement. Refused unless the claim is OPEN, when {@code until} is not after the sheet's today, and
215	     * when the claim is dated in a closed period. */
216	    @Transactional
217	    public Claim defer(String sheetId, String user, long claimId, LocalDate until) {
218	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
219	        refuseClosed(sheetId, claim.getDate());
220	        if (claim.getStatus() != ClaimStatus.OPEN) throw new ClaimStatusChangeException();
221	        if (!until.isAfter(sheets.today(sheetId))) throw new ClaimDeferException();
222	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
223	                .orElseThrow(PersonNotFoundException::new);
224	        RollupService.Snapshot before = rollup.snapshot(sheetId);
225	        claim.setDeferredUntil(until);
226	        claims.flush();
227	        record("CLAIM_DEFERRED", user, person, claim, claim.getNumber(), "until=" + until);
228	        rollup.recordSince(sheetId, user, before);
229	        return claim;
230	    }
231	
232	    /** A steward's re-date of an OPEN or PENDING claim to {@code date}. Its due-by stays as it was fixed
233	     * and a figure a statement bound it to stays bound; its period follows the new date, and when the sheet
234	     * numbers by period and the new date lies in another period (or none) than the old, it is given the
235	     * next number of that period's sequence, its old number never used again. Refused when the user is not
236	     * a steward, unless the claim is OPEN or PENDING, when the claim or the new date is in a closed period,
237	     * and when the new date is after its person's retirement date. */
238	    @Transactional
239	    public Claim redate(String sheetId, String user, long claimId, LocalDate date) {
240	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
241	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
242	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
243	            throw new ClaimStatusChangeException();
244	        }
245	        refuseClosed(sheetId, claim.getDate());
246	        refuseClosed(sheetId, date);
247	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
248	                .orElseThrow(PersonNotFoundException::new);
249	        person.requireClaimable(date);
250	        RollupService.Snapshot before = rollup.snapshot(sheetId);
251	        LocalDate old = claim.getDate();
252	        if (sheets.numbersByPeriod(sheetId) && !periodOf(sheetId, old).equals(periodOf(sheetId, date))) {
253	            claim.setNumber(nextNumber(sheetId, date));
254	        }
255	        claim.setDate(date);
256	        claims.flush();
257	        record("CLAIM_REDATED", user, person, claim, claim.getNumber(), "old=" + old, "new=" + date);
258	        rollup.recordSince(sheetId, user, before);
259	        return claim;
260	    }
261	
262	    /** The id of the sheet's period containing {@code date}; empty when none does. */
263	    private Optional<Long> periodOf(String sheetId, LocalDate date) {
264	        return periods.findBySheetIdOrderByFromAsc(sheetId).stream()
265	                .filter(p -> !date.isBefore(p.getFrom()) && !date.isAfter(p.getTo()))
266	                .findFirst()
267	                .map(p -> p.getId());
268	    }
269	
270	    /** Split {@code amount} (more than 0.00 and less than the claim's amount) off an OPEN claim: the
271	     * claim keeps the rest and loses any figure a statement bound it to; a new OPEN claim of the split-off
272	     * amount, with the same person, date and note, is given the next number, is opened by the user, has
273	     * its due-by fixed now from the terms in force on its date and names the claim's number as the one
274	     * it was split from. Refused unless the claim is OPEN and not deferred on the sheet's today, and when
275	     * it is dated in a closed period. Both claims are returned, the original first. */
276	    @Transactional
277	    public List<Claim> split(String sheetId, String user, long claimId, BigDecimal amount) {
278	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
279	        refuseClosed(sheetId, claim.getDate());
280	        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheets.today(sheetId))) {
281	            throw new ClaimStatusChangeException();
282	        }
283	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) throw new ClaimSplitException();
284	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
285	                .orElseThrow(PersonNotFoundException::new);
286	        RollupService.Snapshot before = rollup.snapshot(sheetId);
287	        claim.setAmount(claim.getAmount().subtract(amount));
288	        claim.unbind();
289	        Claim split = new Claim(sheetId, person.getId(), amount, claim.getDate(), claim.getNote(), null);
290	        split.setDueBy(claim.getDate().plusDays(termsOf(sheetId, person, claim.getDate())));
291	        split.setListed(sheets.nextInSequence(sheetId, "listed"));
292	        split.setStatus(ClaimStatus.OPEN);
293	        split.setNumber(nextNumber(sheetId, claim.getDate()));
294	        split.setOpenedBy(user);
295	        split.setSplitFrom(claim.getNumber());
296	        split = claims.saveAndFlush(split);
297	        log(user, person, split);
298	        record("CLAIM_SPLIT", user, person, claim, claim.getNumber(), "into=" + split.getNumber());
299	        record("CLAIM_OPENED", user, person, split, split.getNumber());
300	        rollup.recordSince(sheetId, user, before);
301	        return List.of(claim, split);
302	    }
303	
304	    /** A steward's approval of a PENDING claim: it becomes SETTLED, fixing what is due on it then (its
305	     * live figure, which no statement binds while it is PENDING, together with its late charge then).
306	     * Refused unless the claim is PENDING, when the user is not a steward or opened the claim, and when it
307	     * has no proofs and that due is above the proof threshold in force on its date. */
308	    @Transactional
309	    public Claim approve(String sheetId, String user, long claimId) {
310	        Claim claim = lockPending(sheetId, user, claimId);
311	        if (user.equals(claim.getOpenedBy())) throw new ClaimNotStewardException();
312	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
313	                .orElseThrow(PersonNotFoundException::new);
314	        RollupService.Snapshot before = rollup.snapshot(sheetId);
315	        BigDecimal figure = rollup.dueOf(claim, person);
316	        BigDecimal due = rollup.liveDueOf(claim, figure);
317	        refuseUnproved(claim, due);
318	        claim.setSettledDue(due);
319	        claim.setStatus(ClaimStatus.SETTLED);
320	        claims.flush();
321	        log(user, person, claim);
322	        record("CLAIM_APPROVED", user, person, claim, claim.getNumber(), "due=" + dueText(due));
323	        notifyWatchers(user, person, claim);
324	        rollup.recordSince(sheetId, user, before);
325	        return claim;
326	    }
327	
328	    /** Raise the claim's proofs count by one. Refused when the claim is SETTLED or VOID, and when it is
329	     * dated in a closed period. */
330	    @Transactional
331	    public Claim addProof(String sheetId, String user, long claimId) {
332	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
333	        refuseClosed(sheetId, claim.getDate());
334	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
335	            throw new ClaimStatusChangeException();
336	        }
337	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
338	                .orElseThrow(PersonNotFoundException::new);
339	        claim.addProof();
340	        claims.flush();
341	        record("CLAIM_PROOF_ADDED", user, person, claim, claim.getNumber(), "proofs=" + claim.getProofs());
342	        return claim;
343	    }
344	
345	    /** A steward's rejection of a PENDING claim, for {@code reason}: it goes back to OPEN, bound again
346	     * by its person's last statement if that statement included it. Refused unless the claim is
347	     * PENDING, and when the user is not a steward. */
348	    @Transactional
349	    public Claim reject(String sheetId, String user, long claimId, String reason) {
350	        Claim claim = lockPending(sheetId, user, claimId);
351	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
352	                .orElseThrow(PersonNotFoundException::new);
353	        RollupService.Snapshot before = rollup.snapshot(sheetId);
354	        claim.setStatus(ClaimStatus.OPEN);
355	        claims.flush();
356	        log(user, person, claim);
357	        record("CLAIM_REJECTED", user, person, claim, claim.getNumber(), "reason=" + reason);
358	        rollup.recordSince(sheetId, user, before);
359	        return claim;
360	    }
361	
362	    /** A move, by a role the permission matrix allows to reassign (a steward by default), of a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its
363	     * number and date, loses any figure a statement bound it to (it is live again until its new
364	     * person's next statement), and is listed as its new person's newest claim. Refused when the user's
365	     * role may not reassign, when the claim is SETTLED or VOID, is a correction (it corrects a claim of its
366	     * own person) or already belongs to the person, when it is dated in a closed period, and when it
367	     * is dated after the new person's retirement date. */
368	    @Transactional
369	    public Claim reassign(String sheetId, String user, long claimId, long personId) {
370	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
371	        if (!settings.allowed(sheetId, user, Action.REASSIGN)) throw new ClaimNotStewardException();
372	        refuseClosed(sheetId, claim.getDate());
373	        ClaimStatus status = claim.getStatus();
374	        if ((status != ClaimStatus.DRAFT && status != ClaimStatus.OPEN && status != ClaimStatus.PENDING)
375	                || claim.isCorrection() || claim.getPersonId() == personId) {
376	            throw new ClaimReassignException();
377	        }
378	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
379	                .orElseThrow(PersonNotFoundException::new);
380	        Person to = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
381	        to.requireClaimable(claim.getDate());
382	        RollupService.Snapshot before = rollup.snapshot(sheetId);
383	        claim.setPersonId(to.getId());
384	        claim.unbind();
385	        claim.setListed(sheets.nextInSequence(sheetId, "listed"));
386	        claims.flush();
387	        record("CLAIM_REASSIGNED", user, to, claim, claim.getNumber(), "from=" + from.getName(), "to=" + to.getName());
388	        rollup.recordSince(sheetId, user, before);
389	        return claim;
390	    }
391	
392	    /** A steward's re-settle of a SETTLED claim: it is fixed again at what would be due on it now were
393	     * it OPEN and bound by no statement (its person's rate and grade, the sheet's floor and its late
394	     * charge, all as they are now). Refused unless the claim is SETTLED, when the user is not a
395	     * steward, and when it is dated in a closed period. */
396	    @Transactional
397	    public Claim resettle(String sheetId, String user, long claimId) {
398	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
399	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
400	        refuseClosed(sheetId, claim.getDate());
401	        if (claim.getStatus() != ClaimStatus.SETTLED) throw new ClaimStatusChangeException();
402	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
403	                .orElseThrow(PersonNotFoundException::new);
404	        RollupService.Snapshot before = rollup.snapshot(sheetId);
405	        BigDecimal old = claim.getSettledDue();
406	        BigDecimal due = rollup.openShownOf(claim, person);
407	        claim.setSettledDue(due);
408	        claims.flush();
409	        log(user, person, claim);
410	        record("CLAIM_RESETTLED", user, person, claim, claim.getNumber(), "old=" + dueText(old), "new=" + dueText(due));
411	        notifyWatchers(user, person, claim);
412	        rollup.recordSince(sheetId, user, before);
413	        return claim;
414	    }
415	
416	    /** Refuse a void of the SETTLED claim unless the user is a steward and the sheet's today is at most
417	     * 7 days after the date its status log first shows it SETTLED. */
418	    private void refuseLateVoid(String sheetId, String user, Claim claim) {
419	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
420	        LocalDate settled = logs.findByClaimIdInOrderByIdAsc(List.of(claim.getId())).stream()
421	                .filter(entry -> entry.getStatus() == ClaimStatus.SETTLED)
422	                .map(ClaimLog::getDate)
423	                .findFirst()
424	                .orElseThrow(ClaimStatusChangeException::new);
425	        if (sheets.today(sheetId).isAfter(settled.plusDays(7))) throw new ClaimVoidLateException();
426	    }
427	
428	    /** The PENDING claim, locked, for a steward to approve or reject. */
429	    private Claim lockPending(String sheetId, String user, long claimId) {
430	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
431	        refuseClosed(sheetId, claim.getDate());
432	        if (claim.getStatus() != ClaimStatus.PENDING) throw new ClaimStatusChangeException();
433	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
434	        return claim;
435	    }
436	
437	    private static String dueText(BigDecimal due) {
438	        return due == null ? "n/a" : due.toPlainString();
439	    }
440	
441	    /** The figure the claim shows and totals now, without its late charge or floor; null when it has no figure
442	     * (see {@link RollupService#figureOf}). */
443	    public BigDecimal figureOf(Claim claim, Person person) {
444	        return rollup.figureOf(claim, person);
445	    }
446	
447	    /** What is due on the claim as it shows and totals now, its late charge included; null when it has
448	     * no figure (see {@link RollupService#shownOf}). */
449	    public BigDecimal shownOf(Claim claim, Person person) {
450	        return rollup.shownOf(claim, person);
451	    }
452	
453	    /** Write the status the claim has now to its log, with the sheet's today and what is due on it as
454	     * it shows now. */
455	    private void log(String user, Person person, Claim claim) {
456	        logs.save(new ClaimLog(claim.getId(), claim.getStatus(), user, sheets.today(claim.getSheetId()),
457	                rollup.shownOf(claim, person)));
458	    }
459	
460	    /** Record a change to the claim; {@code number}, the number it has (or had), follows when there is one,
461	     * then any {@code extra} fields. */
462	    private void record(String event, String user, Person person, Claim claim, String number, String... extra) {
463	        List<String> fields = new ArrayList<>(List.of("person=" + person.getName(),
464	                "amount=" + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
465	                "date=" + claim.getDate()));
466	        if (number != null) fields.add("number=" + number);
467	        fields.addAll(List.of(extra));
468	        audit.change(event, claim.getSheetId(), user, fields.toArray(String[]::new));
469	    }
470	
471	    /** Notify each user watching the person, in the order they started watching, that the claim was
472	     * settled, approved or re-settled. */
473	    private void notifyWatchers(String user, Person person, Claim claim) {
474	        for (PersonWatch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
475	            audit.change("NOTIFY", claim.getSheetId(), user, "user=" + watch.getUser(), "person=" + person.getName(),
476	                    "number=" + claim.getNumber());
477	        }
478	    }
479	
480	    /** The number a claim dated {@code date} is given when opened now: within the period containing
481	     * that date ({@code <period name>-<n>}, or {@code X-<n>} when none does) while the sheet numbers by
482	     * period, otherwise the next sheet-wide number. */
483	    private String nextNumber(String sheetId, LocalDate date) {
484	        if (!sheets.numbersByPeriod(sheetId)) return String.valueOf(sheets.nextClaimNumber(sheetId));
485	        return periods.findBySheetIdOrderByFromAsc(sheetId).stream()
486	                .filter(p -> !date.isBefore(p.getFrom()) && !date.isAfter(p.getTo()))
487	                .findFirst()
488	                .map(p -> p.getName() + "-" + sheets.nextInSequence(sheetId, "period:" + p.getId()))
489	                .orElseGet(() -> "X-" + sheets.nextInSequence(sheetId, "none"));
490	    }
491	
492	    /** Whether a settle by {@code user} of a claim whose due is {@code due} needs a steward's approval:
493	     * the user is a clerk and the due is above the sheet's clerk limit. */
494	    private boolean overLimit(String sheetId, String user, BigDecimal due) {
495	        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return false;
496	        BigDecimal limit = settings.clerkLimit(sheetId);
497	        return limit != null && due.compareTo(limit) > 0;
498	    }
499	
500	    /** Refuse a settle or approval of the claim, whose due is {@code due}, while it has no proofs and that
501	     * due is above the proof threshold in force on its date (a due that is n/a is within any threshold). */
502	    private void refuseUnproved(Claim claim, BigDecimal due) {
503	        if (due == null || claim.getProofs() > 0) return;
504	        BigDecimal threshold = settings.proofThresholdOn(claim.getSheetId(), claim.getDate());
505	        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimProofRequiredException();
506	    }
507	
508	    /** Refuse an open of the claim, whose due is {@code due}, while its note is empty and that due is
509	     * above the note threshold in force on its date (a due that is n/a is within any threshold). */
510	    private void refuseNoteless(Claim claim, BigDecimal due) {
511	        if (due == null || !noteOf(claim.getNote()).isEmpty()) return;
512	        BigDecimal threshold = settings.noteThresholdOn(claim.getSheetId(), claim.getDate());
513	        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimNoteRequiredException();
514	    }
515	
516	    /** Refuse a correction (a negative {@code amount}) that does not name, by number, a SETTLED claim of
517	     * the person, and a claim that names one without being a correction. */
518	    private void refuseBadCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
519	        if (amount.signum() >= 0) {
520	            if (corrects != null) throw new ClaimCorrectionException();
521	            return;
522	        }
523	        if (corrects == null) throw new ClaimCorrectionException();
524	        claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
525	                .filter(corrected -> corrected.getStatus() == ClaimStatus.SETTLED)
526	                .orElseThrow(ClaimCorrectionException::new);
527	    }
528	
529	    /** Refuse a change that touches {@code date} when a closed period of the sheet contains it. */
530	    private void refuseClosed(String sheetId, LocalDate date) {
531	        if (periods.closedOn(sheetId, date)) throw new ClaimPeriodClosedException();
532	    }
533	
534	    private static String noteOf(String note) {
535	        return note == null ? "" : note.trim();
536	    }
537	
538	    /** The terms a claim of the person dated {@code date} is due by: the person's own terms, else those
539	     * of their grade in force on that date, else the sheet's then. */
540	    private int termsOf(String sheetId, Person person, LocalDate date) {
541	        return person.getTerms() != null ? person.getTerms() : settings.termsFor(sheetId, person.gradeOn(date), date);
542	    }
543	}
